B.bSn=new A.dZ(B.d8,"Treatment record in the patient file, like the paper file: every session numbered in order with date, doctor, tooth, treatment, cost and payments. It replaces the Visits tab.","\u0633\u062c\u0644 \u0627\u0644\u0645\u0639\u0627\u0644\u062c\u0629 \u0641\u064a \u0645\u0644\u0641 \u0627\u0644\u0645\u0631\u064a\u0636\u060c \u0645\u062b\u0644 \u0627\u0644\u0645\u0644\u0641 \u0627\u0644\u0648\u0631\u0642\u064a: \u0643\u0644 \u062c\u0644\u0633\u0629 \u0645\u0631\u0642\u0651\u0645\u0629 \u0628\u0627\u0644\u062a\u0631\u062a\u064a\u0628 \u0645\u0639 \u0627\u0644\u062a\u0627\u0631\u064a\u062e \u0648\u0627\u0644\u0637\u0628\u064a\u0628 \u0648\u0627\u0644\u0633\u0646 \u0648\u0627\u0644\u0639\u0644\u0627\u062c \u0648\u0627\u0644\u062a\u0643\u0644\u0641\u0629 \u0648\u0627\u0644\u062f\u0641\u0639\u0627\u062a. \u064a\u062d\u0644 \u0645\u062d\u0644 \u062a\u0628\u0648\u064a\u0628 \u0627\u0644\u0632\u064a\u0627\u0631\u0627\u062a.")
B.bSu=new A.dZ(B.d8,"Add old record: copy sessions from the paper file with their date, procedures and what was paid then.","\u0625\u0636\u0627\u0641\u0629 \u0633\u062c\u0644 \u0642\u062f\u064a\u0645: \u0627\u0646\u0642\u0644 \u0627\u0644\u062c\u0644\u0633\u0627\u062a \u0645\u0646 \u0627\u0644\u0645\u0644\u0641 \u0627\u0644\u0648\u0631\u0642\u064a \u0645\u0639 \u062a\u0627\u0631\u064a\u062e\u0647\u0627 \u0648\u0625\u062c\u0631\u0627\u0621\u0627\u062a\u0647\u0627 \u0648\u0627\u0644\u0645\u0628\u0644\u063a \u0627\u0644\u0645\u062f\u0641\u0648\u0639 \u062d\u064a\u0646\u0647\u0627.")
B.bSo=new A.dZ(B.d8,"Export the treatment record to PDF, laid out like the paper patient file, in Arabic or English.","\u062a\u0635\u062f\u064a\u0631 \u0633\u062c\u0644 \u0627\u0644\u0645\u0639\u0627\u0644\u062c\u0629 \u0625\u0644\u0649 PDF \u0628\u0646\u0641\u0633 \u0634\u0643\u0644 \u0645\u0644\u0641 \u0627\u0644\u0645\u0631\u064a\u0636 \u0627\u0644\u0648\u0631\u0642\u064a\u060c \u0628\u0627\u0644\u0639\u0631\u0628\u064a\u0629 \u0623\u0648 \u0627\u0644\u0625\u0646\u062c\u0644\u064a\u0632\u064a\u0629.")
B.bSt=new A.dZ(B.d8,"Custom tooth numbering in Settings \u2192 Clinic setup: show teeth as a number and quadrant (e.g. 6 UR) instead of international numbers, with your own number for each tooth. One setting for the whole clinic, on every device.","\u062a\u0631\u0642\u064a\u0645 \u0623\u0633\u0646\u0627\u0646 \u0645\u062e\u0635\u0635 \u0641\u064a \u0627\u0644\u0625\u0639\u062f\u0627\u062f\u0627\u062a \u2190 \u0625\u0639\u062f\u0627\u062f \u0627\u0644\u0639\u064a\u0627\u062f\u0629: \u0627\u0639\u0631\u0636 \u0627\u0644\u0623\u0633\u0646\u0627\u0646 \u0628\u0631\u0642\u0645 \u0648\u0631\u0628\u0639 \u0627\u0644\u0641\u0643 (\u0645\u062b\u0644\u0627\u064b 6 \u0639\u0644\u0648\u064a \u0623\u064a\u0645\u0646) \u0628\u062f\u0644 \u0627\u0644\u062a\u0631\u0642\u064a\u0645 \u0627\u0644\u062f\u0648\u0644\u064a\u060c \u0645\u0639 \u0631\u0642\u0645\u0643 \u0627\u0644\u062e\u0627\u0635 \u0644\u0643\u0644 \u0633\u0646. \u0625\u0639\u062f\u0627\u062f \u0648\u0627\u062d\u062f \u0644\u0644\u0639\u064a\u0627\u062f\u0629 \u0643\u0644\u0647\u0627\u060c \u0639\u0644\u0649 \u0643\u0644 \u0627\u0644\u0623\u062c\u0647\u0632\u0629.")
B.bSr=new A.dZ(B.d8,"Quicker tooth choice: pick Upper or Lower and Right or Left, then choose the tooth from the list or type it. The dental chart has a Find a tooth button.","\u0627\u062e\u062a\u064a\u0627\u0631 \u0623\u0633\u0631\u0639 \u0644\u0644\u0633\u0646: \u0627\u062e\u062a\u0631 \u0639\u0644\u0648\u064a \u0623\u0648 \u0633\u0641\u0644\u064a \u0648\u064a\u0645\u064a\u0646 \u0623\u0648 \u064a\u0633\u0627\u0631\u060c \u062b\u0645 \u0627\u062e\u062a\u0631 \u0627\u0644\u0633\u0646 \u0645\u0646 \u0627\u0644\u0642\u0627\u0626\u0645\u0629 \u0623\u0648 \u0627\u0643\u062a\u0628\u0647. \u0648\u0641\u064a \u0645\u062e\u0637\u0637 \u0627\u0644\u0623\u0633\u0646\u0627\u0646 \u0632\u0631 \u0627\u0644\u0628\u062d\u062b \u0639\u0646 \u0633\u0646.")
B.bSN=new A.dZ(B.d8,"Treatment plans and visits: add the same service to several teeth at once, one item for each tooth.","\u062e\u0637\u0637 \u0627\u0644\u0639\u0644\u0627\u062c \u0648\u0627\u0644\u0632\u064a\u0627\u0631\u0627\u062a: \u0623\u0636\u0641 \u0627\u0644\u062e\u062f\u0645\u0629 \u0646\u0641\u0633\u0647\u0627 \u0644\u0639\u062f\u0629 \u0623\u0633\u0646\u0627\u0646 \u062f\u0641\u0639\u0629 \u0648\u0627\u062d\u062f\u0629\u060c \u0628\u0646\u062f \u0644\u0643\u0644 \u0633\u0646.")
B.bSs=new A.dZ(B.d8,"Leave rules for each role in Settings \u2192 Clinic setup \u2192 Leaves: notice, longest leave, days per year, hours off per request and per month, and no two people of the same role off together.","\u0642\u0648\u0627\u0639\u062f \u0627\u0644\u0625\u062c\u0627\u0632\u0627\u062a \u0644\u0643\u0644 \u062f\u0648\u0631 \u0641\u064a \u0627\u0644\u0625\u0639\u062f\u0627\u062f\u0627\u062a \u2190 \u0625\u0639\u062f\u0627\u062f \u0627\u0644\u0639\u064a\u0627\u062f\u0629 \u2190 \u0627\u0644\u0625\u062c\u0627\u0632\u0627\u062a: \u0645\u062f\u0629 \u0627\u0644\u062a\u0642\u062f\u064a\u0645 \u0627\u0644\u0645\u0633\u0628\u0642\u060c \u0623\u0637\u0648\u0644 \u0625\u062c\u0627\u0632\u0629\u060c \u0627\u0644\u0623\u064a\u0627\u0645 \u0641\u064a \u0627\u0644\u0633\u0646\u0629\u060c \u0633\u0627\u0639\u0627\u062a \u0627\u0644\u0625\u0630\u0646 \u0641\u064a \u0627\u0644\u0645\u0631\u0629 \u0648\u0641\u064a \u0627\u0644\u0634\u0647\u0631\u060c \u0648\u0645\u0646\u0639 \u063a\u064a\u0627\u0628 \u0634\u062e\u0635\u064a\u0646 \u0645\u0646 \u0627\u0644\u062f\u0648\u0631 \u0646\u0641\u0633\u0647 \u0645\u0639\u064b\u0627.")
B.bSv=new A.dZ(B.d8,"Hour off: ask for time off within a day, approved like leave. Request forms show what is left and say clearly when a rule is broken.","\u0627\u0644\u0625\u0630\u0646 \u0627\u0644\u0633\u0627\u0639\u064a: \u0627\u0637\u0644\u0628 \u0625\u0630\u0646\u064b\u0627 \u062e\u0644\u0627\u0644 \u0627\u0644\u064a\u0648\u0645\u060c \u0648\u064a\u064f\u0648\u0627\u0641\u0642 \u0639\u0644\u064a\u0647 \u0645\u062b\u0644 \u0627\u0644\u0625\u062c\u0627\u0632\u0629. \u062a\u0639\u0631\u0636 \u0646\u0645\u0627\u0630\u062c \u0627\u0644\u0637\u0644\u0628 \u0627\u0644\u0631\u0635\u064a\u062f \u0627\u0644\u0645\u062a\u0628\u0642\u064a \u0648\u062a\u0648\u0636\u062d \u0633\u0628\u0628 \u0627\u0644\u0631\u0641\u0636 \u0639\u0646\u062f \u0645\u062e\u0627\u0644\u0641\u0629 \u0627\u0644\u0642\u0648\u0627\u0639\u062f.")
B.bSO=new A.dZ(B.f6,"Appointments calendar is more compact: more of the working day fits on screen, and each appointment shows just the patient name (hover or tap for the time).","\u062a\u0642\u0648\u064a\u0645 \u0627\u0644\u0645\u0648\u0627\u0639\u064a\u062f \u0623\u0643\u062b\u0631 \u0627\u062e\u062a\u0635\u0627\u0631\u064b\u0627: \u064a\u0638\u0647\u0631 \u062c\u0632\u0621 \u0623\u0643\u0628\u0631 \u0645\u0646 \u0633\u0627\u0639\u0627\u062a \u0627\u0644\u0639\u0645\u0644 \u0639\u0644\u0649 \u0627\u0644\u0634\u0627\u0634\u0629\u060c \u0648\u064a\u0639\u0631\u0636 \u0643\u0644 \u0645\u0648\u0639\u062f \u0627\u0633\u0645 \u0627\u0644\u0645\u0631\u064a\u0636 \u0641\u0642\u0637 (\u0645\u0631\u0651\u0631 \u0627\u0644\u0645\u0624\u0634\u0631 \u0623\u0648 \u0627\u0636\u063a\u0637 \u0644\u0645\u0639\u0631\u0641\u0629 \u0627\u0644\u0648\u0642\u062a).")
B.bSK=new A.dZ(B.f6,"WhatsApp buttons on the computer open the WhatsApp app directly, without the browser page first.","\u0623\u0632\u0631\u0627\u0631 \u0648\u0627\u062a\u0633\u0627\u0628 \u0639\u0644\u0649 \u0627\u0644\u062d\u0627\u0633\u0648\u0628 \u062a\u0641\u062a\u062d \u062a\u0637\u0628\u064a\u0642 \u0648\u0627\u062a\u0633\u0627\u0628 \u0645\u0628\u0627\u0634\u0631\u0629\u060c \u062f\u0648\u0646 \u0627\u0644\u0645\u0631\u0648\u0631 \u0628\u0635\u0641\u062d\u0629 \u0627\u0644\u0645\u062a\u0635\u0641\u062d.")
B.bSq=new A.dZ(B.d8,"Send a WhatsApp reminder straight from the appointment dialog; it is marked as sent.","\u0623\u0631\u0633\u0644 \u062a\u0630\u0643\u064a\u0631 \u0648\u0627\u062a\u0633\u0627\u0628 \u0645\u0628\u0627\u0634\u0631\u0629 \u0645\u0646 \u0646\u0627\u0641\u0630\u0629 \u0627\u0644\u0645\u0648\u0639\u062f\u060c \u0648\u064a\u064f\u0633\u062c\u064e\u0651\u0644 \u0623\u0646\u0647 \u0623\u064f\u0631\u0633\u0644.")
B.bSS=new A.dZ(B.d8,"Roles and permissions in Settings \u2192 Clinic setup: choose which menu sections and patient file tabs each role sees, on every device.","\u0627\u0644\u0623\u062f\u0648\u0627\u0631 \u0648\u0627\u0644\u0635\u0644\u0627\u062d\u064a\u0627\u062a \u0641\u064a \u0627\u0644\u0625\u0639\u062f\u0627\u062f\u0627\u062a \u2190 \u0625\u0639\u062f\u0627\u062f \u0627\u0644\u0639\u064a\u0627\u062f\u0629: \u0627\u062e\u062a\u0631 \u0623\u0642\u0633\u0627\u0645 \u0627\u0644\u0642\u0627\u0626\u0645\u0629 \u0648\u062a\u0628\u0648\u064a\u0628\u0627\u062a \u0645\u0644\u0641 \u0627\u0644\u0645\u0631\u064a\u0636 \u0627\u0644\u062a\u064a \u064a\u0631\u0627\u0647\u0627 \u0643\u0644 \u062f\u0648\u0631\u060c \u0639\u0644\u0649 \u0643\u0644 \u0627\u0644\u0623\u062c\u0647\u0632\u0629.")
B.bSw=new A.dZ(B.f6,"Updated the libraries the app is built on, for stability and security.","\u062a\u062d\u062f\u064a\u062b \u0645\u0643\u062a\u0628\u0627\u062a \u0627\u0644\u062a\u0637\u0628\u064a\u0642 \u0644\u0645\u0632\u064a\u062f \u0645\u0646 \u0627\u0644\u062b\u0628\u0627\u062a \u0648\u0627\u0644\u0623\u0645\u0627\u0646.")
B.bSI=new A.dZ(B.l7,"Windows: setup now installs the Microsoft components the app needs, so it starts on a freshly installed computer.","\u0648\u064a\u0646\u062f\u0648\u0632: \u064a\u062b\u0628\u0651\u062a \u0628\u0631\u0646\u0627\u0645\u062c \u0627\u0644\u0625\u0639\u062f\u0627\u062f \u0627\u0644\u0622\u0646 \u0645\u0643\u0648\u0651\u0646\u0627\u062a \u0645\u0627\u064a\u0643\u0631\u0648\u0633\u0648\u0641\u062a \u0627\u0644\u062a\u064a \u064a\u062d\u062a\u0627\u062c\u0647\u0627 \u0627\u0644\u062a\u0637\u0628\u064a\u0642\u060c \u0641\u064a\u0639\u0645\u0644 \u0639\u0644\u0649 \u062d\u0627\u0633\u0648\u0628 \u062c\u062f\u064a\u062f \u0645\u0628\u0627\u0634\u0631\u0629.")
B.bSU=new A.dZ(B.f6,"Dental chart: the buttons sit in their own card beside the chart, so the 2D chart and the 3D view are larger.","\u0645\u062e\u0637\u0637 \u0627\u0644\u0623\u0633\u0646\u0627\u0646: \u0627\u0644\u0623\u0632\u0631\u0627\u0631 \u0641\u064a \u0628\u0637\u0627\u0642\u0629 \u0645\u0633\u062a\u0642\u0644\u0629 \u0628\u062c\u0627\u0646\u0628 \u0627\u0644\u0645\u062e\u0637\u0637\u060c \u0641\u0635\u0627\u0631 \u0627\u0644\u0645\u062e\u0637\u0637 \u0627\u0644\u062b\u0646\u0627\u0626\u064a \u0648\u0627\u0644\u0639\u0631\u0636 \u062b\u0644\u0627\u062b\u064a \u0627\u0644\u0623\u0628\u0639\u0627\u062f \u0623\u0643\u0628\u0631.")
B.bSV=new A.dZ(B.l7,'Laptop screens: the appointments toolbar moved up beside New appointment so the calendar gets more room, the week view fits all seven days, and "Rooms now" lists every room with its doctor and patient.',"\u0634\u0627\u0634\u0627\u062a \u0627\u0644\u062d\u0648\u0627\u0633\u064a\u0628 \u0627\u0644\u0645\u062d\u0645\u0648\u0644\u0629: \u0627\u0646\u062a\u0642\u0644 \u0634\u0631\u064a\u0637 \u0623\u062f\u0648\u0627\u062a \u0627\u0644\u0645\u0648\u0627\u0639\u064a\u062f \u0625\u0644\u0649 \u062c\u0627\u0646\u0628 \xab\u0645\u0648\u0639\u062f \u062c\u062f\u064a\u062f\xbb \u0644\u064a\u0623\u062e\u0630 \u0627\u0644\u062a\u0642\u0648\u064a\u0645 \u0645\u0633\u0627\u062d\u0629 \u0623\u0643\u0628\u0631\u060c \u0648\u064a\u062a\u0633\u0639 \u0639\u0631\u0636 \u0627\u0644\u0623\u0633\u0628\u0648\u0639 \u0644\u0644\u0623\u064a\u0627\u0645 \u0627\u0644\u0633\u0628\u0639\u0629\u060c \u0648\u062a\u0639\u0631\u0636 \xab\u0627\u0644\u063a\u0631\u0641 \u0627\u0644\u0622\u0646\xbb \u0643\u0644 \u063a\u0631\u0641\u0629 \u0645\u0639 \u0637\u0628\u064a\u0628\u0647\u0627 \u0648\u0645\u0631\u064a\u0636\u0647\u0627.")
